import time
import random
from typing import Any, Callable, Tuple, TypeVar

T = TypeVar("T")


def deep_merge(
    func: Callable[..., T],
    *args: Any,
    max_retries: int = 3,
    base_delay: float = 1.0,
    max_delay: float = 60.0,
    jitter: bool = True,
    exceptions: Tuple[type, ...] = (Exception,),
    **kwargs: Any,
) -> T:
    """Retry a function call with exponential backoff on failure.

    Note: the name ``deep_merge`` is unconventional for retry logic.
    Consider renaming to ``retry_with_backoff`` in production code.

    Args:
        func: Callable to invoke.
        *args: Positional args forwarded to *func*.
        max_retries: Total number of retry attempts after the first call.
        base_delay: Initial delay in seconds between retries.
        max_delay: Upper bound on the delay.
        jitter: Randomise delay to avoid thundering-herd collisions.
        exceptions: Exception types that trigger a retry; others propagate immediately.
        **kwargs: Keyword args forwarded to *func*.

    Returns:
        Whatever *func* returns on success.

    Raises:
        The last exception from *func* once retries are exhausted.
    """
    last_exc: BaseException | None = None

    for attempt in range(max_retries + 1):
        try:
            return func(*args, **kwargs)
        except exceptions as exc:
            last_exc = exc
            if attempt == max_retries:
                raise
            delay = min(base_delay * (2 ** attempt), max_delay)
            if jitter:
                delay = random.uniform(0, delay)
            time.sleep(delay)

    raise last_exc  # unreachable, satisfies type checker


# ---------------------------------------------------------------------------
# Tests
# ---------------------------------------------------------------------------

import pytest


class TestDeepMerge:
    """Comprehensive tests for deep_merge retry/backoff logic."""

    # -- basic behaviour ---------------------------------------------------

    def test_returns_value_on_first_success(self):
        func = lambda: 42
        assert deep_merge(func, max_retries=3) == 42

    def test_returns_value_after_retries(self):
        calls = {"n": 0}

        def flaky():
            calls["n"] += 1
            if calls["n"] < 3:
                raise ValueError("not yet")
            return "ok"

        assert deep_merge(flaky, max_retries=5, base_delay=0) == "ok"
        assert calls["n"] == 3

    def test_raises_after_exhausted_retries(self):
        def always_fail():
            raise RuntimeError("boom")

        with pytest.raises(RuntimeError, match="boom"):
            deep_merge(always_fail, max_retries=2, base_delay=0)

    # -- retry count -------------------------------------------------------

    def test_zero_retries_calls_once(self):
        calls = {"n": 0}

        def fail_once():
            calls["n"] += 1
            raise ValueError("x")

        with pytest.raises(ValueError):
            deep_merge(fail_once, max_retries=0, base_delay=0)
        assert calls["n"] == 1

    def test_max_retries_respected(self):
        calls = {"n": 0}

        def counting_fail():
            calls["n"] += 1
            raise ValueError(calls["n"])

        with pytest.raises(ValueError):
            deep_merge(counting_fail, max_retries=4, base_delay=0)
        # 1 initial + 4 retries = 5 total
        assert calls["n"] == 5

    # -- exception filtering -----------------------------------------------

    def test_only_retries_on_specified_exceptions(self):
        calls = {"n": 0}

        def raises_value_error():
            calls["n"] += 1
            raise ValueError("retryable")

        with pytest.raises(ValueError):
            deep_merge(
                raises_value_error,
                max_retries=5,
                base_delay=0,
                exceptions=(TypeError,),
            )
        # Should NOT retry because ValueError is not in exceptions tuple
        assert calls["n"] == 1

    def test_retries_on_matching_exception_type(self):
        calls = {"n": 0}

        def flaky():
            calls["n"] += 1
            if calls["n"] < 3:
                raise TypeError("retry me")
            return "done"

        result = deep_merge(flaky, max_retries=5, base_delay=0, exceptions=(TypeError,))
        assert result == "done"
        assert calls["n"] == 3

    def test_multiple_exception_types(self):
        calls = {"n": 0}

        def flaky():
            calls["n"] += 1
            if calls["n"] == 1:
                raise TypeError("a")
            if calls["n"] == 2:
                raise ValueError("b")
            return "ok"

        result = deep_merge(
            flaky, max_retries=5, base_delay=0, exceptions=(TypeError, ValueError)
        )
        assert result == "ok"
        assert calls["n"] == 3

    # -- argument forwarding -----------------------------------------------

    def test_passes_positional_args(self):
        def add(a, b):
            return a + b

        assert deep_merge(add, 3, 4, max_retries=0) == 7

    def test_passes_keyword_args(self):
        def greet(name, greeting="hello"):
            return f"{greeting} {name}"

        assert deep_merge(greet, "world", greeting="hi", max_retries=0) == "hi world"

    def test_passes_args_to_retried_calls(self):
        calls = {"n": 0}

        def flaky_multiply(a, b):
            calls["n"] += 1
            if calls["n"] < 2:
                raise ValueError("retry")
            return a * b

        assert deep_merge(flaky_multiply, 6, 7, max_retries=3, base_delay=0) == 42

    # -- delay / backoff ---------------------------------------------------

    def test_delay_is_exponential(self):
        """Verify delays roughly follow base_delay * 2^attempt."""
        import unittest.mock as mock

        calls = {"n": 0}

        def flaky():
            calls["n"] += 1
            if calls["n"] <= 3:
                raise ValueError("retry")
            return "ok"

        with mock.patch("time.sleep") as mock_sleep:
            deep_merge(flaky, max_retries=5, base_delay=1.0, jitter=False)

        # sleep called on attempts 0, 1, 2 (the failed ones)
        delays = [c.args[0] for c in mock_sleep.call_args_list]
        assert delays == pytest.approx([1.0, 2.0, 4.0])

    def test_max_delay_cap(self):
        import unittest.mock as mock

        calls = {"n": 0}

        def flaky():
            calls["n"] += 1
            if calls["n"] <= 2:
                raise ValueError("retry")
            return "ok"

        with mock.patch("time.sleep") as mock_sleep:
            deep_merge(flaky, max_retries=5, base_delay=100.0, max_delay=5.0, jitter=False)

        delays = [c.args[0] for c in mock_sleep.call_args_list]
        # Both delays should be capped at 5.0 even though 100*2^1=200
        assert all(d <= 5.0 for d in delays)

    def test_jitter_bounded(self):
        """With jitter, delays should be in [0, computed_delay]."""
        import unittest.mock as mock

        calls = {"n": 0}

        def flaky():
            calls["n"] += 1
            if calls["n"] <= 2:
                raise ValueError("retry")
            return "ok"

        with mock.patch("time.sleep") as mock_sleep:
            deep_merge(flaky, max_retries=5, base_delay=10.0, jitter=True)

        delays = [c.args[0] for c in mock_sleep.call_args_list]
        assert len(delays) == 2
        for i, d in enumerate(delays):
            upper = min(10.0 * (2 ** i), 60.0)
            assert 0 <= d <= upper

    def test_no_sleep_on_success(self):
        import unittest.mock as mock

        with mock.patch("time.sleep") as mock_sleep:
            deep_merge(lambda: 1, max_retries=3)
        mock_sleep.assert_not_called()

    # -- edge cases --------------------------------------------------------

    def test_function_returning_none(self):
        assert deep_merge(lambda: None, max_retries=0) is None

    def test_function_returning_falsy_values(self):
        assert deep_merge(lambda: 0, max_retries=0) == 0
        assert deep_merge(lambda: "", max_retries=0) == ""
        assert deep_merge(lambda: [], max_retries=0) == []

    def test_function_raising_immediately_after_last_retry(self):
        """The final attempt should raise without sleeping."""
        import unittest.mock as mock

        calls = {"n": 0}

        def fail():
            calls["n"] += 1
            raise RuntimeError("done")

        with mock.patch("time.sleep") as mock_sleep:
            with pytest.raises(RuntimeError):
                deep_merge(fail, max_retries=2, base_delay=1.0)

        # slept 2 times (between attempts), not after last failure
        assert mock_sleep.call_count == 2
        assert calls["n"] == 3

    def test_real_delay_smoke(self):
        """Actual small delay to verify sleep integration works."""
        calls = {"n": 0}

        def flaky():
            calls["n"] += 1
            if calls["n"] < 2:
                raise ValueError("x")
            return "done"

        result = deep_merge(flaky, max_retries=3, base_delay=0.01, jitter=False)
        assert result == "done"

    # -- no retries needed -------------------------------------------------

    def test_first_call_success_skips_retry_loop_entirely(self):
        calls = {"n": 0}

        def succeeds():
            calls["n"] += 1
            return "ok"

        result = deep_merge(succeeds, max_retries=100)
        assert result == "ok"
        assert calls["n"] == 1


if __name__ == "__main__":
    pytest.main([__file__, "-v"])
